function reset(){if(confirm('Effacer toutes les données nutrition, mesures, séances et objectifs ? Cette action est irréversible. Exporte d’abord une sauvegarde si nécessaire.')){S=DEF();save();render()}}
function bk(){const d=S.lastExp?(Date.now()-new Date(S.lastExp+'T12:00:00'))/864e5:99;return S.meas.length+S.meals.length>5&&d>14?'<div class="mutedbox warn">Pense à exporter tes données : aucune sauvegarde récente enregistrée.</div>':''}
function chart(title,pts,col,u,d=1,gl){pts=pts.filter(p=>ok(p.v));if(pts.length<2)return `<div class="card"><h2>${title}</h2><div class="mu">Il faut au moins deux mesures.</div></div>`;const W=320,H=110,t0=+new Date(pts[0].d),t1=+new Date(pts[pts.length-1].d),vs=pts.map(p=>p.v),N=pts.length,mn=Math.min(...vs),mx=Math.max(...vs);let lo=mn,hi=mx;if(ok(gl)){lo=Math.min(lo,gl);hi=Math.max(hi,gl)}const pad=(hi-lo)*.2||1;lo-=pad;hi+=pad;const X=p=>8+(+new Date(p.d)-t0)/(t1-t0||1)*(W-16),Y=v=>H-8-(v-lo)/(hi-lo)*(H-16),a=pts[0],z=pts[N-1],xs=pts.map(p=>(+new Date(p.d)-t0)/864e5),mxm=xs.reduce((q,x)=>q+x,0)/N,mym=vs.reduce((q,x)=>q+x,0)/N,den=xs.reduce((q,x)=>q+(x-mxm)**2,0),sl=den>0?xs.reduce((q,x,k)=>q+(x-mxm)*(vs[k]-mym),0)/den:0,ty=x=>mym+sl*(x-mxm),id='c'+Math.random().toString(36).slice(2,7);return `<div class="card"><div class="split"><h2>${title}</h2><span><b style="color:${col}">${r(z.v,d)} ${u}</b> <span class="mu">(${sg(z.v-a.v)})</span></span></div><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(title)}">${ok(gl)?`<line x1="8" x2="${W-8}" y1="${Y(gl)}" y2="${Y(gl)}" stroke-dasharray="4 4" stroke-width="1.5" style="stroke:var(--k)"/>`:''}${N>=3?`<line x1="${X(a)}" x2="${X(z)}" y1="${Y(ty(0))}" y2="${Y(ty(xs[N-1]))}" stroke-dasharray="2 4" stroke-width="1.5" style="stroke:${col};opacity:.55"/>`:''}<polyline fill="none" style="stroke:${col}" stroke-width="2.5" points="${pts.map(p=>X(p)+','+Y(p.v)).join(' ')}"/>${pts.map(p=>`<circle cx="${X(p)}" cy="${Y(p.v)}" r="3" style="fill:${col}"/><circle cx="${X(p)}" cy="${Y(p.v)}" r="13" fill="transparent" data-t="${esc(r(p.v,d)+' '+u+' · '+fd(p.d))}" onclick="tipC('${id}',this)"/>`).join('')}</svg><div class="mu" id="${id}" aria-live="polite" style="min-height:20px">Touche un point pour lire sa valeur.${ok(gl)?' Pointillé orange : objectif.':''}</div><div class="li mu"><span>${fd(a.d)}</span><span>min ${r(mn,d)} · max ${r(mx,d)}</span><span>${fd(z.d)}</span></div></div>`}
function smooth(){const W=sorted().filter(x=>ok(x.w)&&(!rng||x.d>=dstr(rng)));return W.map(p=>{const t=+new Date(p.d),a=W.filter(q=>{const k=t-+new Date(q.d);return k>=0&&k<=6*864e5});return{d:p.d,v:sum(a,'w')/a.length}})}
function dailyPlan(){
 const t=targets(),ms=dayMeals(),protein=sum(ms,'p'),waterMl=S.water[day]||0;
 const proteinTarget=t?PK()*t.w:0,waterTarget=t?t.w*35:2000;
 const weekDate=new Date(day+'T12:00:00');weekDate.setDate(weekDate.getDate()-((weekDate.getDay()+6)%7));const weekStart=localDate(weekDate);
 const trainingDays=new Set(S.sets.filter(x=>x.d>=weekStart&&x.d<=day).map(x=>x.d)).size;
 const trainingTarget=Math.max(1,Math.min(7,Math.round(n(S.p.wg)||3)));
 const percent=(v,target)=>Math.max(0,Math.min(100,target>0?v/target*100:0));
 const bar=(label,value,target,unit)=>'<div class="daily-goal"><div class="split"><span>'+label+'</span><b>'+value+' / '+target+' '+unit+'</b></div><div class="bar"><i style="width:'+percent(value,target)+'%"></i></div></div>';
 const last=sorted().filter(m=>m.d<=day).slice(-1)[0];
 const due=!last||Math.floor((new Date(day+'T12:00:00')-new Date(last.d+'T12:00:00'))/86400000)>=7;
 return '<div class="card daily-plan"><div class="hero-kicker">PETITS PAS · GRANDS PROGRÈS</div><h2 style="margin:4px 0">Cap sur tes objectifs</h2><p class="mu">Concentre-toi sur la prochaine action, pas sur la perfection.</p><div class="daily-goals">'+(proteinTarget?bar('Protéines',r(protein,0),r(proteinTarget,0),'g'):'')+bar('Hydratation',r(waterMl/1000,2),r(waterTarget/1000,1),'L')+bar('Musculation cette semaine',trainingDays,trainingTarget,'séances')+'</div><div class="actions daily-actions"><button class="p sm" onclick="tab=\'force\';render()">Ouvrir mes séances</button><button class="p sm secondary" onclick="tab=\'mes\';render()">Body Tracker</button><button class="p sm secondary" onclick="water(250)">+250 ml d’eau</button></div>'+(due?'<p class="mu daily-note">'+(last?'Ton dernier relevé date de '+Math.floor((new Date(day+'T12:00:00')-new Date(last.d+'T12:00:00'))/86400000)+' jours.':'Pas encore de mensurations enregistrées.')+' Une mesure hebdomadaire suffit pour suivre la tendance.</p>':'')+'</div>';
}

function nutritionDashboard(eat,budget,mac,mt,targetP,t){
if(!t)return '<section class="card nutrition-dashboard"><div class="split"><h2>Ton bilan nutrition</h2><span class="tag">À configurer</span></div>'+onbBox()+'</section>';
const kcalLeft=budget-eat;
const metric=(label,v,target,unit,color)=>{target=Number(target)||0;v=Number(v)||0;const remain=target-v,pct=target>0?Math.min(100,v/target*100):0;return '<div class="nutrition-macro"><div class="split"><span>'+label+'</span><b>'+r(v,1)+' <small>/ '+r(target,1)+unit+'</small></b></div><div class="bar"><i style="width:'+pct+'%;background:'+color+'"></i></div><div class="nutrition-macro-foot"><span>'+Math.round(pct)+' %</span><strong>'+(remain>=0?r(remain,1)+unit+' restants':r(Math.abs(remain),1)+unit+' dépassés')+'</strong></div></div>'};
return '<section class="card nutrition-dashboard"><div class="split"><div><div class="hero-kicker">TON BILAN · '+fd(day)+'</div><h2>Nutrition du jour</h2></div><span class="tag">Objectif quotidien</span></div><div class="nutrition-calories"><div><div class="mu">Consommées</div><div class="nutrition-kcal">'+r(eat)+' <small>kcal</small></div><div class="nutrition-kcal-sub">Budget : '+r(budget)+' kcal</div></div><div class="nutrition-remaining"><div class="mu">'+(kcalLeft>=0?'Il te reste':'Dépassement')+'</div><div class="nutrition-kcal">'+r(Math.abs(kcalLeft))+' <small>kcal</small></div><div class="nutrition-kcal-sub">'+(kcalLeft>=0?'pour aujourd’hui':'au-dessus du budget')+'</div></div></div><div class="bar nutrition-calorie-bar"><i style="width:'+(budget>0?Math.min(100,eat/budget*100):0)+'%;background:'+(kcalLeft<0?'var(--k)':'var(--b)')+'"></i></div><div class="nutrition-macro-grid">'+metric('Protéines',mac.p,targetP,' g','var(--b)')+metric('Glucides',mac.c,mt&&mt.c,' g','var(--m)')+metric('Lipides',mac.f,mt&&mt.f,' g','var(--k)')+'</div><p class="mu nutrition-footnote">Objectifs indicatifs. Le budget tient compte de la part d’activité configurée dans Profil ; les calories dépensées restent des estimations.</p></section>';
}
function quickMealSlots(){return '<div class="quick-meal-slots" aria-label="Choisir le repas">'+SLOTS.map((z,i)=>'<button type="button" class="meal-slot-chip'+(z===curSlot()?' active':'')+'" onclick="setQuickSlot('+i+')">'+['☀','◷','＋','☾','•••'][i]+' '+esc(z)+'</button>').join('')+'</div>'}
function setQuickSlot(i){const z=SLOTS[i];if(!z)return;const s=document.getElementById('qss');if(s)s.value=z;document.querySelectorAll('.meal-slot-chip').forEach((b,j)=>b.classList.toggle('active',j===i));const manual=document.querySelector('#mealForm [name=slot]');if(manual)manual.value=z}

function vJour(){const ms=dayMeals(),ws=dayWork(),sets=daySets(),eat=kcal(ms),t=targets(),waterMl=S.water[day]||0,mac={p:sum(ms,'p'),c:sum(ms,'c'),f:sum(ms,'f')};const targetP=t?PK()*t.w:null;const sk=strK(day),burn=kcal(ws)+sk,ebp=(ok(n(S.p.eb))?n(S.p.eb):50)/100,budget=t?t.target+burn*ebp:0,mt=t?{p:PK()*t.w,f:.9*t.w,c:Math.max(0,(budget-4*PK()*t.w-9*.9*t.w)/4)}:null;const slots=SLOTS.map(s=>{const it=ms.filter(x=>x.slot===s);if(!it.length)return'';return `<h3>${s} · ${r(kcal(it))} kcal</h3>`+it.map(x=>`<div class="li"><span>${esc(x.name)} ${x.g?`<span class="mu">${r(x.g)} g</span>`:''}<br><span class="mu">${r(x.k)} kcal${ok(x.p)?` · P ${r(x.p,1)} g · G ${r(x.c,1)} g · L ${r(x.f,1)} g`:''}</span></span><span class="actions"><button class="x" aria-label="Modifier" onclick="editMeal('${x.id}')">✎</button><button class="x" aria-label="Supprimer" onclick="del('meals','${x.id}')">×</button></span></div>`).join('')}).join('');
const foods=[...new Set(S.meals.map(x=>x.name).reverse())].slice(0,6).map(x=>{const l=[...S.meals].reverse().find(m=>m.name===x),g=l&&l.source==='base'&&l.g?Math.round(l.g):'';return `<button class="p sm secondary" data-food="${esc(x)}" data-g="${g}" onclick="const f=document.querySelector('[name=food]'),q=document.querySelector('[name=g]');f.value=this.dataset.food;q.value=this.dataset.g;q.focus();q.select&&q.select()">${esc(x)}${g?` · ${g} g`:''}</button>`}).join('');
const coach=coachBox(t,mac,targetP,waterMl);const workoutList=(sk>0?`<div class="li"><span>Musculation estimée<br><span class="mu">d'après ${r(sum(sets,'sets'))} séries de l'onglet Musculation (2,5 min par série)</span></span><span class="mu">${r(sk)} kcal</span></div>`:'')+ws.map(x=>`<div class="li"><span>${esc(x.type)} · ${r(x.min||0)} min<br><span class="mu">${r(x.k)} kcal estimées ${x.note?'· '+esc(x.note):''}</span></span><span class="actions"><button class="x" onclick="editWork('${x.id}')" aria-label="Modifier">✎</button><button class="x" onclick="del('work','${x.id}')" aria-label="Supprimer">×</button></span></div>`).join('');
const targetBox=t?`<div class="g2"><div class="metric" style="text-align:center"><div class="mu">Calories</div>${ring(budget>0?eat/budget:0,r(Math.abs(budget-eat)),budget-eat>=0?'kcal restantes':'kcal en trop',budget-eat>=0?'var(--b)':'var(--k)')}<div class="mu">mangé ${r(eat)} sur un budget de ${r(budget)} kcal</div></div><div class="metric"><div class="mu">Protéines</div><div class="big">${r(mac.p,1)} g</div><div class="mu">objectif indicatif ${r(targetP,0)} g</div><div class="bar"><i style="width:${Math.min(100,mac.p/Math.max(1,targetP)*100)}%"></i></div></div></div><p class="mu">Sport estimé : ${r(burn)} kcal, dont ${r(burn*ebp)} ajoutées à ton budget (${r(ebp*100)} %, réglable dans Profil). Ce sont des estimations.</p>${budget<t.bmr?'<p class="warn mu">Attention : la cible saisie est inférieure au métabolisme de base estimé. Évite de maintenir un déficit important sans avis professionnel.</p>':''}`:onbBox();
return `<section class="hero"><div><div class="hero-kicker">Performance · Nutrition · Force</div><div class="hero-title">Ton suivi, tes progrès.</div><div class="hero-sub">${streakN()>1?`Série en cours : ${streakN()} jours. Continue comme ça.`:'Un jour à la fois. Des données claires pour avancer.'}</div></div><div style="min-width:200px"><label for="dayPick">JOUR DE SUIVI</label><div class="actions" style="flex-wrap:nowrap;margin-top:5px"><button class="p secondary sm" style="margin:0" onclick="shiftDay(-1)" aria-label="Jour précédent">‹</button><input id="dayPick" type="date" value="${day}" onchange="day=this.value||day;render()" style="margin:0"><button class="p secondary sm" style="margin:0" onclick="shiftDay(1)" aria-label="Jour suivant">›</button></div>${day!==localDate()?'<button class="p sm" style="margin:6px 0 0" onclick="day=localDate();render()">Revenir à aujourd\'hui</button>':''}</div></section>${nutritionDashboard(eat,budget,mac,mt,targetP,t)}<section class="quick-actions" aria-label="Actions rapides"><button class="quick-action primary" onclick="quickJump('qs')"><span class="qa-icon">＋</span><span><b>Ajouter un repas</b><small>Noter ce que tu manges</small></span></button><button class="quick-action" onclick="water(250)"><span class="qa-icon">↗</span><span><b>Boire de l’eau</b><small>Ajouter 250 ml</small></span></button><button class="quick-action" onclick="tab='force';render()"><span class="qa-icon">↗</span><span><b>Démarrer une séance</b><small>Musculation</small></span></button></section>
${coach}<div class="card" id="weight-water"><div class="split"><h2>Poids et eau</h2><span class="tag">Suivi rapide</span></div><form onsubmit="quickW(event)" class="row"><input id="weightInput" name="w" type="number" step="0.1" min="1" aria-label="Poids du jour" placeholder="Poids du jour (kg)"><button class="p sm" style="flex:0 0 auto">Enregistrer</button></form><div class="li"><span>Eau · ${r(waterMl/1000,2)} L${t?` / repère indicatif ${r(t.w*.035,1)} L`:''}</span><span><button class="p sm" onclick="water(250)">+250 ml</button><button class="p sm" onclick="water(500)">+500 ml</button><button class="x" onclick="water(-250)" aria-label="Retirer 250 ml">−</button></span></div></div>
<div class="card" id="meal-entry"><div class="split"><h2>Repas</h2><span class="tag">+ Ajouter</span></div>${quickMealSlots()}${qsBox()}<details${mealEdit?' open':''} style="margin-top:10px"><summary class="mu" style="cursor:pointer;padding:6px 0">Saisie manuelle (kcal)</summary><form id="mealForm" onsubmit="addMeal(event)"><div class="row"><label>Moment<select name="slot">${SLOTS.map(s=>`<option${s===curSlot()?' selected':''}>${s}</option>`).join('')}</select></label><label>Aliment<input name="food" list="fl" placeholder="Ex. riz cuit" autocomplete="off" required></label><label>Quantité (g)<input name="g" type="number" min="0.1" step="any" placeholder="Grammes"></label><label>Ou kcal manuelles<input name="k" type="number" min="0" step="any" placeholder="kcal"></label></div><datalist id="fl">${allF().map(f=>`<option value="${esc(f[0])}">`).join('')}</datalist><button class="p">${mealEdit?'Enregistrer les modifications':'Ajouter le repas'}</button>${mealEdit?'<button type="button" class="p secondary" onclick="mealEdit=null;render()">Annuler</button>':''}</form></details><details style="margin-top:10px"><summary class="mu" style="cursor:pointer;padding:6px 0">Chercher un produit ou un code-barres (Open Food Facts)</summary><form onsubmit="offSearch(event)" style="margin-top:6px"><div class="row"><label>Base de produits Open Food Facts<input name="q" placeholder="Produit ou code-barres"></label><button class="p sm" style="flex:0 0 auto">Rechercher</button></div></form><div id="off"></div></details>${foods}<div class="actions" style="margin-top:8px"><button class="p sm secondary" onclick="copyY()">Copier les repas de la veille</button></div>${slots||'<div class="mutedbox" style="margin-top:10px">Rien de noté ce jour-là. <button class="p sm" onclick="$(&quot;#qs&quot;).focus()">Ajouter un aliment</button></div>'}</div>
<div class="card"><h2>Activité du jour</h2>${workoutList||'<p class="mu">Aucune activité ajoutée pour cette date.</p>'}<details${workEdit?' open':''} style="margin-top:8px"><summary class="mu" style="cursor:pointer;padding:6px 0">Ajouter une activité</summary><form id="workForm" onsubmit="addWork(event)"><div class="row"><label>Activité<select name="type">${ACT.map(a=>`<option>${a[0]}</option>`).join('')}<option>Autre</option></select></label><label>Durée (min)<input name="min" type="number" min="1" step="1" placeholder="Minutes"></label><label>Kcal manuelles (facultatif)<input name="k" type="number" min="0" step="any" placeholder="Sinon estimées"></label></div><input name="note" placeholder="Notes (facultatif)"><button class="p">${workEdit?'Enregistrer les modifications':'Ajouter une activité'}</button>${workEdit?'<button type="button" class="p secondary" onclick="workEdit=null;render()">Annuler</button>':''}</form></details><p class="mu">Les calories dépensées sont des estimations très variables : une partie (réglable dans Profil) est ajoutée à ton budget du jour.</p></div>`}
let bodyView='front',bodyFocus='waist',bodyRange=90;
const GOODDIR={chest:1,arm:1,thigh:1,calf:1,waist:-1};
const bodyVal=k=>sorted().filter(m=>m.d<=day&&ok(m[k])).pop()||null;
const dcls=(d,k)=>{const g=GOODDIR[k]||0;return d===null||Math.abs(d)<.05||!g?'delta-flat':(d*g>0?'dg':'db')};
function bodyProgressCharts(){
 const all=sorted(),latest=all.length?all[all.length-1].d:null;
 const filtered=all.filter(m=>!latest||bodyRange===0||(+new Date(latest+'T12:00:00')- +new Date(m.d+'T12:00:00'))<=bodyRange*864e5);
 const ranges=[[7,'7 jours'],[30,'30 jours'],[90,'90 jours'],[365,'1 an'],[0,'Tout']];
 const chips=ranges.map(([v,l])=>'<button class="p sm '+(bodyRange===v?'':'secondary')+'" onclick="bodyRange='+v+';render()">'+l+'</button>').join('');
 const specs=[['w','Poids','var(--b)','kg',1],['waist','Tour de taille','var(--k)','cm',1],['chest','Pectoraux','var(--m)','cm',1],['arm','Bras','var(--b)','cm',1],['thigh','Cuisse','var(--m)','cm',1]];
 const charts=specs.map(([k,label,color,unit,d])=>chart(label,filtered.map(m=>({d:m.d,v:m[k]})),color,unit,d)).join('');
 const count=filtered.length;
 return '<details class="ux-fold" data-ux-key="measure-charts"><summary>Graphiques des mensurations <span class="ux-fold-note">'+count+' relevé'+(count>1?'s':'')+' · poids, taille, bras…</span></summary><div class="ux-fold-inner"><div class="card bt-trends"><p class="mu">Choisis une période pour comparer tes mesures.</p><div class="actions bt-range">'+chips+'</div></div>'+charts+'</div></details>';
}
function vMes(){
 const cm=S.meas.find(x=>x.d===day)||{},ordered=sorted().reverse();
 const latest=ordered[0]||null,prior=latest?ordered.slice(1).find(m=>m.d<latest.d)||null:null;
 const filled=MF.filter(([k])=>latest&&ok(latest[k])).length,completion=latest?Math.round(filled/MF.length*100):0;
 const trend=(k)=>latest&&prior&&ok(latest[k])&&ok(prior[k])?{delta:latest[k]-prior[k],from:prior[k],to:latest[k]}:null;
 const weightTrend=trend('w'),waistTrend=trend('waist');
 const mini=(label,t,unit)=>'<div class="bt-mini"><span>'+label+'</span><b class="'+(t?dcls(t.delta,label==='Poids'?'w':'waist'):'')+'">'+(t?(t.delta>0?'+':'')+r(t.delta,1)+' '+unit:'—')+'</b><small>'+(t?'vs relevé précédent':'2 relevés requis')+'</small></div>';
 const snapshot='<div class="card bt-snapshot"><div class="split"><div><div class="hero-kicker">TON POINT DE DÉPART</div><h2 style="margin:4px 0">Bilan express</h2></div><span class="tag">'+(latest?fd(latest.d):'À commencer')+'</span></div>'+(latest?'<div class="bt-completion"><div class="split"><span>Mensurations renseignées</span><b>'+filled+' / '+MF.length+'</b></div><div class="bar"><i style="width:'+completion+'%"></i></div></div><div class="bt-minis">'+mini('Poids',weightTrend,'kg')+mini('Tour de taille',waistTrend,'cm')+'</div><p class="mu bt-hint">Compare des relevés réalisés dans des conditions similaires. Une variation isolée ne suffit pas à conclure : regarde la tendance sur plusieurs semaines.</p>':'<p class="mu">Enregistre ton premier relevé pour commencer à suivre tes tendances. Tu peux laisser les champs que tu ne connais pas vides.</p>')+'</div>';
 const hist=ordered.map(m=>{const b=bf(m);return `<div class="li"><span><b>${fd(m.d)}</b><br><span class="mu">${MF.filter(([k])=>ok(m[k])).map(([k,l])=>`${l.split(' ')[0]} ${r(m[k],1)}${k==='w'?' kg':' cm'}`).join(' · ')}${b!==null?` · gras estimé ${r(b,1)} %`:''}</span></span><button class="x" aria-label="Supprimer le relevé du ${fd(m.d)}" onclick="del('meas','${m.id||m.d}')">×</button></div>`}).join('');
 const zones=[['neck','Cou',120,70,'front'],['chest','Poitrine',120,113,'front'],['arm','Bras',65,150,'front'],['wrist','Poignet',58,165,'front'],['waist','Taille',120,180,'front'],['hip','Hanches',120,201,'front'],['thigh','Cuisse',101,267,'front'],['calf','Mollet',94,326,'front'],['chest','Haut du dos',120,118,'back'],['waist','Bas du dos',120,181,'back'],['arm','Bras',65,150,'back'],['wrist','Poignet',58,165,'back'],['hip','Hanches',120,201,'back'],['thigh','Cuisse',101,267,'back'],['calf','Mollet',94,326,'back']];
 const shown=zones.filter(z=>z[4]===bodyView);
 const value=k=>{const m=bodyVal(k);return m?`${r(m[k],1)} ${k==='w'?'kg':'cm'}`:'—'};
 const cur=bodyVal(bodyFocus),prevForCurrent=cur?sorted().filter(m=>m.d<cur.d&&ok(m[bodyFocus])).pop():null,currentDate=cur?cur.d:null,focusDelta=cur&&prevForCurrent?cur[bodyFocus]-prevForCurrent[bodyFocus]:null;
 const focusLabel=(MF.find(x=>x[0]===bodyFocus)||['','Mensuration'])[1];
 const chip=(k,label,cls='')=>`<div role="button" tabindex="0" class="body-stat ${cls} ${bodyFocus===k?'selected':''}" onclick="bodyFocus='${k}';render()" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();bodyFocus='${k}';render()}"><span>${label}</span><b>${value(k)}</b></div>`;
 const silhouette=bodyView==='front'?`<circle cx="120" cy="34" r="23" fill="url(#skin2)" stroke="#6e8790" stroke-width="1.4"/><path d="M107 55 L107 70 Q89 73 75 83 L54 143 Q51 154 61 157 Q69 159 74 148 L91 110 L88 174 Q87 192 96 207 L88 264 L81 365 Q80 378 92 379 Q102 379 104 366 L119 282 L136 366 Q139 380 150 377 Q160 374 157 362 L150 264 L143 207 Q153 190 151 174 L149 110 L166 148 Q171 160 181 156 Q190 152 185 141 L165 83 Q151 73 133 70 L133 55 Z" fill="url(#skin2)" stroke="#6e8790" stroke-width="1.4" stroke-linejoin="round"/><path d="M107 70 Q120 79 133 70 M91 110 Q120 126 149 110 M91 111 Q104 140 100 173 M149 111 Q136 140 140 173 M88 174 Q120 187 151 174 M96 207 Q120 218 143 207 M93 263 Q120 271 153 263" fill="none" stroke="#718b94" stroke-opacity=".65" stroke-width="1.2"/>`:`<circle cx="120" cy="34" r="23" fill="url(#skin2)" stroke="#6e8790" stroke-width="1.4"/><path d="M107 55 L107 70 Q89 73 75 83 L54 143 Q51 154 61 157 Q69 159 74 148 L91 110 L88 174 Q87 192 96 207 L88 264 L81 365 Q80 378 92 379 Q102 379 104 366 L119 282 L136 366 Q139 380 150 377 Q160 374 157 362 L150 264 L143 207 Q153 190 151 174 L149 110 L166 148 Q171 160 181 156 Q190 152 185 141 L165 83 Q151 73 133 70 L133 55 Z" fill="url(#skin2)" stroke="#6e8790" stroke-width="1.4" stroke-linejoin="round"/><path d="M91 110 Q120 127 149 110 M96 120 Q106 132 105 153 M144 120 Q134 132 135 153 M91 174 Q120 184 149 174 M97 207 Q120 217 143 207 M120 78 L120 263 M100 133 Q120 145 140 133 M99 155 Q120 168 141 155" fill="none" stroke="#718b94" stroke-opacity=".8" stroke-width="1.3"/><path d="M104 126 Q120 143 136 126 L132 163 Q120 171 108 163 Z" fill="#c5ff4a" opacity=".06"/>`;
 const markers=shown.map(z=>{const [k,label,x,y]=z,active=bodyFocus===k;return `<g class="body-marker ${active?'active':''}" role="button" tabindex="0" aria-label="Sélectionner ${label}" onclick="bodyFocus='${k}';render()" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();bodyFocus='${k}';render()}"><circle cx="${x}" cy="${y}" r="${active?7:5}"/><text x="${x+10}" y="${y+3}">${label.toUpperCase()}</text></g>`}).join('');
 const rows=MF.map(([k,l])=>{const L=ordered.filter(m=>ok(m[k]));if(L.length<2)return '';const b=L[0][k],a=L[1][k],d=b-a;return `<div class="compare-row"><span>${l}<br><span class="mu">${fd(L[1].d)} → ${fd(L[0].d)}</span></span><span>${r(a,1)} → ${r(b,1)}</span><b class="${dcls(d,k)}">${d>0?'+':''}${r(d,1)} ${k==='w'?'kg':'cm'}</b></div>`}).join('');
 const compare=`<div class="card"><div class="split"><h2>Comparaison des mensurations</h2><span class="tag">2 dernières valeurs par zone</span></div>${rows?`<p class="mu">Chaque zone est comparée à sa valeur précédente. Vert : évolution favorable (muscle en hausse, taille en baisse).</p><div>${rows}</div>`:'<p class="mu">Ajoute au moins deux relevés d\'une même zone pour voir ton évolution.</p>'}</div>`;
 return `${snapshot}${bodyProgressCharts()}<div class="body-head"><div><div class="hero-kicker">BODY TRACKER · ${fd(day)}</div><h2 style="font-size:clamp(22px,3vw,30px);margin:5px 0 4px">Ton corps, tes données.</h2><p class="mu">Sélectionne une zone sur la silhouette ou dans les cartes pour suivre sa progression.</p></div><button class="p sm ${bodyFocus==='w'?'':'secondary'}" style="margin:0" onclick="bodyFocus='w';render()">Poids</button></div>
 <div class="body-board"><div class="body-side">${chip('neck','Cou','lime')}${chip('chest','Poitrine')}${chip('arm','Bras')}${chip('wrist','Poignet')}</div>
 <div class="body-art"><div class="body-art-top"><span>VUE ${bodyView==='front'?'AVANT':'ARRIÈRE'}</span><span class="body-live"><i></i> SUIVI ACTIF</span></div><div style="display:flex;justify-content:center;margin:8px 0 4px"><div class="body-switch"><button class="${bodyView==='front'?'on':''}" onclick="bodyView='front';render()">Face</button><button class="${bodyView==='back'?'on':''}" onclick="bodyView='back';render()">Dos</button></div></div><svg viewBox="0 0 240 410" role="img" aria-label="Silhouette interactive, vue ${bodyView==='front'?'avant':'arrière'}" class="human-svg" style="width:100%;max-width:290px;display:block"><defs><linearGradient id="skin2" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#46616b"/><stop offset="1" stop-color="#1c3039"/></linearGradient><linearGradient id="glow2" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#c5ff4a" stop-opacity=".08"/><stop offset=".5" stop-color="#c5ff4a" stop-opacity=".95"/><stop offset="1" stop-color="#c5ff4a" stop-opacity=".08"/></linearGradient></defs>${silhouette}<path d="M100 84 Q120 91 140 84 L140 117 Q120 126 100 117 Z" fill="#c5ff4a" opacity="${bodyFocus==='chest'?.18:.06}"/><path d="M98 178 Q120 185 142 178 L141 198 Q120 205 99 198 Z" fill="#c5ff4a" opacity="${bodyFocus==='waist'?.2:.07}"/><g stroke="url(#glow2)" stroke-width="2"><path d="M100 72 H140"/><path d="M79 113 H161"/><path d="M87 179 H153"/><path d="M91 199 H149"/><path d="M94 264 H146"/><path d="M91 322 H106 M134 322 H151"/><path d="M65 139 L88 151 M152 151 L175 139"/></g>${markers}</svg><div class="body-caption">Choisis un repère · les valeurs viennent de tes relevés</div></div>
 <div class="body-side">${chip('waist','Tour de taille','lime')}${chip('hip','Hanches')}${chip('thigh','Cuisse')}${chip('calf','Mollet')}</div></div>
 <div class="measure-focus"><div class="split"><div><div class="hero-kicker">ZONE SÉLECTIONNÉE</div><h2 style="margin:4px 0">${esc(focusLabel)}</h2></div><span class="tag">${bodyFocus==='w'?'KG':'CM'}</span></div><div class="big">${value(bodyFocus)}</div><div class="mu">${currentDate?`Dernière valeur enregistrée : ${fd(currentDate)}`:'Aucune mesure pour cette zone'}</div><div class="measure-delta"><div class="delta-tile"><span>Relevé précédent</span><b>${prevForCurrent?`${r(prevForCurrent[bodyFocus],1)} ${bodyFocus==='w'?'kg':'cm'}`:'—'}</b></div><div class="delta-tile"><span>Évolution</span><b class="${dcls(focusDelta,bodyFocus)}">${focusDelta===null?'—':`${focusDelta>0?'+':''}${r(focusDelta,1)} ${bodyFocus==='w'?'kg':'cm'}`}</b></div><div class="delta-tile"><span>Nombre de relevés</span><b>${S.meas.filter(m=>ok(m[bodyFocus])).length}</b></div></div></div>
 ${chart('Évolution : '+focusLabel,sorted().map(m=>({d:m.d,v:m[bodyFocus]})),'var(--b)',bodyFocus==='w'?'kg':'cm',1)}<div class="card"><div class="split"><h2>Enregistrer tes mensurations</h2><span class="tag">CM / KG</span></div><form onsubmit="addMeas(event)"><label>Date du relevé<input type="date" name="d" value="${day}" onchange="day=this.value||day;render()" required></label><div class="measure-fields">${MF.map(([k,l,u])=>`<label>${l} (${u})<input name="${k}" type="number" min="0.1" step="0.1" value="${ok(cm[k])?cm[k]:''}" placeholder="${ok(lastOf(k))?`Dernier : ${r(lastOf(k),1)}`:'Ajouter une mesure'}"></label>`).join('')}</div><p class="mu">Pour estimer le pourcentage de graisse avec la formule US Navy, la taille, le cou et le tour de taille sont requis (hanches aussi pour les femmes). C'est une estimation, pas une mesure médicale.</p><button class="p">Enregistrer les mesures</button></form></div><details class="ux-fold" data-ux-key="measure-history"><summary>Comparaisons et historique <span class="ux-fold-note">Évolution entre tes relevés</span></summary><div class="ux-fold-inner">${compare}<div class="card"><h2>Historique des mensurations</h2>${hist||'<p class="mu">Aucune mesure pour le moment.</p>'}</div></div></details>`
}

function vEvo(){const P=sorted().filter(m=>!rng||m.d>=dstr(rng)).map(m=>{const b=bf(m),valid=ok(m.w)&&b!==null;return{...m,b,l:valid?m.w*(1-b/100):null,g:valid?m.w*b/100:null}});const ser=k=>P.map(p=>({d:p.d,v:p[k]}));let summary='<p class="mu">Ajoute au moins deux mesures pour visualiser les tendances.</p>';const W=P.filter(p=>p.l!==null);if(W.length>=2){const a=W[0],z=W[W.length-1];summary=`<div class="g3"><div><div class="big good">${sg(z.l-a.l)}</div><div class="mu">kg masse maigre estimée</div></div><div><div class="big warn">${sg(z.g-a.g)}</div><div class="mu">kg masse grasse estimée</div></div><div><div class="big">${sg(z.w-a.w)}</div><div class="mu">kg poids</div></div></div><p class="mu">La masse maigre et la masse grasse sont dérivées d'une estimation du pourcentage de graisse : les erreurs de mensuration peuvent amplifier les variations. Compare plutôt plusieurs semaines.</p>`}
const dates=[...new Set(S.meals.map(x=>x.d))].sort().slice(-7),avg=dates.length?dates.reduce((s,d)=>s+kcal(dayMeals(d)),0)/dates.length:null;
return `${rangeChips()}<div class="card"><h2>Ton évolution</h2>${summary}${avg!==null?`<p class="mu">Moyenne des jours saisis : <b>${r(avg)} kcal/j</b> sur ${dates.length} jour(s) avec des repas. Ce ne sont pas nécessairement des journées complètes.</p>`:''}</div>${vTrend()}<details class="ux-fold" data-ux-key="evo-charts"><summary>Graphiques détaillés <span class="ux-fold-note">Poids et composition corporelle</span></summary><div class="ux-fold-inner">${chart('Poids',ser('w'),'var(--b)','kg',1,n(S.p.gw))}${chart('Poids lissé (moyenne 7 j)',smooth(),'var(--b)','kg')}${chart('Masse maigre estimée',ser('l'),'var(--m)','kg')}${chart('Masse grasse estimée',ser('g'),'var(--k)','kg')}${chart('% de gras estimé',ser('b'),'var(--k)','%',1)}</div></details>`}
function e1(x){return x.kg*(1+x.reps/30)}
function addSet(e){e.preventDefault();const f=e.target,ex=f.ex.value.trim(),kg=n(f.kg.value),reps=n(f.reps.value),sets=n(f.sets.value)||1,rir=n(f.rir.value),rest=n(f.rest.value);if(!ex||!ok(kg)||kg<0||!ok(reps)||reps<1||!Number.isInteger(reps)||sets<1)return alert('Exercice, charge, répétitions et nombre de séries valides sont nécessaires. Au poids du corps, indique la charge utilisée comme repère.');const obj={id:setEdit||uid(),d:day,ex,kg,reps,sets,rir:ok(rir)?rir:null,rest:ok(rest)?rest:null};if(setEdit){const i=S.sets.findIndex(x=>x.id===setEdit);if(i>=0)S.sets[i]=obj;setEdit=null}else S.sets.push(obj);save();render();if(ok(rest)&&rest>0)startRest(rest);else toast('Série ajoutée')}
function editSet(id){const x=S.sets.find(y=>y.id===id);if(!x)return;setEdit=id;day=x.d;tab='force';render();const f=$('#setForm');if(f){f.ex.value=x.ex;f.kg.value=x.kg;f.reps.value=x.reps;f.sets.value=x.sets;f.rir.value=x.rir??'';f.rest.value=x.rest??'';f.scrollIntoView({behavior:'smooth',block:'center'})}}
function vForceLegacy(){const isPR=x=>{const o=S.sets.filter(y=>y.ex===x.ex&&y.d<x.d);return o.length>0&&e1(x)>Math.max(...o.map(e1))},today=daySets(),used=[...new Set(S.sets.map(x=>x.ex))],names=[...new Set([...used,...EXS])],volume=today.reduce((s,x)=>s+x.kg*x.reps*x.sets,0),records={};S.sets.forEach(x=>records[x.ex]=Math.max(records[x.ex]||0,e1(x)));const hist=today.map(x=>`<div class="li"><span><b>${esc(x.ex)}</b>${isPR(x)?' <span class="tag good">Record</span>':''}<br><span class="mu">${r(x.sets)} séries × ${r(x.reps)} reps à ${r(x.kg,1)} kg${ok(x.rir)?` · RIR ${r(x.rir)}`:''}${ok(x.rest)?` · repos ${r(x.rest)} s`:''}<br>1RM estimé ≈ ${r(e1(x),1)} kg</span></span><span class="actions"><button class="x" onclick="editSet('${x.id}')" aria-label="Modifier">✎</button><button class="x" onclick="del('sets','${x.id}')" aria-label="Supprimer">×</button></span></div>`).join('');
if(!used.includes(selectedExercise))selectedExercise=used.length?used[used.length-1]:'';const by={};S.sets.filter(x=>x.ex===selectedExercise).forEach(x=>by[x.d]=Math.max(by[x.d]||0,e1(x)));const graph=selectedExercise?chart('1RM estimé · '+selectedExercise,Object.keys(by).sort().map(d=>({d,v:by[d]})),'var(--m)','kg',1):'';
return `${vGuide()}<div class="card"><div class="split"><h2>Carnet de musculation</h2><input type="date" value="${day}" onchange="day=this.value||day;render()" style="width:auto;margin:0"></div><div class="g3"><div class="metric"><div class="mu">Entrées</div><div class="big">${today.length}</div></div><div class="metric"><div class="mu">Séries totales</div><div class="big">${today.reduce((s,x)=>s+x.sets,0)}</div></div><div class="metric"><div class="mu">Volume chargé</div><div class="big">${r(volume/1000,1)}</div><div class="mu">tonnes · charge × reps</div></div></div><h3>${setEdit?'Modifier une entrée':'Ajouter un exercice'}</h3><form id="setForm" onsubmit="addSet(event)"><label>Exercice<input name="ex" list="exl" placeholder="Ex. développé couché" required onchange="hintSet(this)"></label><div class="mu" id="setHint"></div><div class="actions" style="margin:6px 0"><span class="mu">Chrono repos :</span>${[60,90,120,180].map(z=>`<button type="button" class="p sm secondary" onclick="startRest(${z})">${Math.floor(z/60)}:${String(z%60).padStart(2,'0')}</button>`).join('')}</div><datalist id="exl">${names.map(x=>`<option value="${esc(x)}">`).join('')}</datalist><div class="row"><label>Charge (kg)<input name="kg" type="number" min="0" step="any" required></label><label>Répétitions par série<input name="reps" type="number" min="1" step="1" required></label><label>Nombre de séries<input name="sets" type="number" min="1" step="1" value="3" required></label></div><div class="row"><label>RIR (facultatif)<input name="rir" type="number" min="0" max="10" step="1" placeholder="Répétitions en réserve"></label><label>Repos en secondes<input name="rest" type="number" min="0" step="5" placeholder="ex. 120"></label></div><button class="p">${setEdit?'Enregistrer':'Ajouter à la séance'}</button>${setEdit?'<button type="button" class="p secondary" onclick="setEdit=null;render()">Annuler</button>':''}</form><h3>Entrées du ${fd(day)}</h3>${hist||'<p class="mu">Aucune entrée pour cette date.</p>'}<p class="mu">L'estimation de 1RM utilise la formule d'Epley ; elle est indicative et moins fiable pour certaines plages de répétitions. Le volume est charge × répétitions × séries.</p></div><details class="ux-fold" data-ux-key="force-library"><summary>Bibliothèque d’exercices <span class="ux-fold-note">Parcourir et ajouter des mouvements</span></summary><div class="ux-fold-inner">${vLib()}</div></details><details class="ux-fold" data-ux-key="force-progress"><summary>Progression par exercice <span class="ux-fold-note">Courbes et records</span></summary><div class="ux-fold-inner"><div class="card"><h2>Progression par exercice</h2><label>Exercice<select onchange="selectedExercise=this.value;render()">${used.map(x=>`<option ${x===selectedExercise?'selected':''}>${esc(x)}</option>`).join('')}</select></label>${graph||'<p class="mu">Ajoute des exercices pour suivre leur progression.</p>'}<h3>Records estimés</h3>${used.map(ex=>`<div class="li"><span>${esc(ex)}</span><b>${r(records[ex],1)} kg</b></div>`).join('')||'<p class="mu">Pas encore de records.</p>'}</div></div></details><details class="ux-fold" data-ux-key="force-tools"><summary>Outils et réglages de séance</summary><div class="ux-fold-inner">${vTools()}</div></details>`}

let workoutEquip='Tous',workoutSearch='',workoutGroup='Tous';
const WORKOUT_TYPES=[['PUSH','Push','Pectoraux · épaules · triceps','↗'],['PULL','Pull','Dos · biceps','↘'],['LEGS','Legs','Quadriceps · ischios · fessiers','↓'],['UPPER','Upper','Tout le haut du corps','↑'],['LOWER','Lower','Tout le bas du corps','⇣'],['FULL BODY','Full Body','Corps entier','✦'],['LIBRE','Libre','Construire sans programme','＋']];
function startWorkout(type){S.draft={id:uid(),d:day,type,startedAt:new Date().toISOString(),exercises:[]};workoutSearch='';workoutGroup='Tous';workoutEquip='Tous';save();render()}
function cancelWorkout(){if(!confirm('Abandonner cette séance en cours ?'))return;S.draft=null;save();render()}
function lastSetsFor(nm){const f=fold(nm),M=x=>({kg:String(x.kg),reps:String(x.reps),rir:x.rir==null?'':String(x.rir)});for(let i=(S.sessions||[]).length-1;i>=0;i--){const e=(S.sessions[i].exercises||[]).find(x=>fold(x.name)===f);if(e&&e.sets&&e.sets.length)return e.sets.map(M)}const L=S.sets.filter(x=>fold(x.ex)===f);if(!L.length)return null;const d=L.map(x=>x.d).sort().pop();return L.filter(x=>x.d===d).slice(0,6).map(M)}
function addWorkoutExerciseName(nm){if(!S.draft)return;const item=LIB.find(x=>fold(x.n)===fold(nm));const group=item?item.g:grpOf(nm);if(S.draft.exercises.some(x=>fold(x.name)===fold(nm))){toast('Cet exercice est déjà dans ta séance');return}S.draft.exercises.push({id:uid(),name:item?item.n:nm,group,sets:lastSetsFor(nm)||[{kg:'',reps:'10',rir:''},{kg:'',reps:'10',rir:''},{kg:'',reps:'10',rir:''}]});workoutSearch='';save();render();if(lastSetsFor(nm))toast('Pré-rempli avec ta dernière séance')}
function addWorkoutExercise(e){e.preventDefault();const f=e.target,nm=String(f.wxpick.value||'').trim();if(!nm)return;addWorkoutExerciseName(nm)}
function workoutAllowedGroups(){const t=S.draft&&S.draft.type;if(t==='PUSH')return ['Pectoraux','Épaules','Triceps'];if(t==='PULL')return ['Dos','Biceps'];if(t==='LEGS')return ['Quadriceps','Ischios','Fessiers','Mollets'];if(t==='LOWER')return ['Quadriceps','Ischios','Fessiers','Mollets','Abdos'];if(t==='UPPER')return ['Pectoraux','Dos','Épaules','Biceps','Triceps','Abdos'];return Object.keys(LIBS)}
function workoutFilter(g){workoutGroup=g;const el=document.getElementById('workout-machine-list');if(el)el.innerHTML=workoutLibraryHTML();const count=document.getElementById('workout-result-count');if(count)count.textContent=workoutLibraryCount()}
function workoutEquipFilter(v){workoutEquip=v;const el=document.getElementById('workout-machine-list');if(el)el.innerHTML=workoutLibraryHTML();const count=document.getElementById('workout-result-count');if(count)count.textContent=workoutLibraryCount()}
function workoutSearchInput(v){workoutSearch=v;const el=document.getElementById('workout-machine-list');if(el)el.innerHTML=workoutLibraryHTML();const count=document.getElementById('workout-result-count');if(count)count.textContent=workoutLibraryCount()}
function workoutFiltered(){const q=fold(workoutSearch),allowed=workoutAllowedGroups();return LIB.filter(x=>allowed.includes(x.g)&&(workoutEquip==='Tous'||x.e===workoutEquip)&&(workoutGroup==='Tous'||x.g===workoutGroup)&&(!q||fold(x.n).includes(q)||fold(x.g).includes(q)))}
function workoutLibraryCount(){return workoutFiltered().length}
function workoutLibraryHTML(){const all=workoutFiltered();return all.length?all.map(x=>'<button type="button" class="workout-machine" data-name="'+esc(x.n)+'" onclick="addWorkoutExerciseName(this.dataset.name)"><span class="workout-machine-icon">'+({'M':'▥','H':'⏣','B':'━','P':'↕','C':'●'}[x.e]||'•')+'</span><span class="workout-machine-copy"><b>'+esc(x.n)+'</b><small>'+esc(x.g)+' · '+EQ[x.e]+'</small></span><span class="workout-machine-add">+</span></button>').join(''):'<p class="mu">Aucun exercice ne correspond à ces filtres. Essaie un autre matériel ou efface la recherche.</p>'}
function draftSet(exid,i,k,v){if(!S.draft)return;const ex=S.draft.exercises.find(x=>x.id===exid);if(!ex||!ex.sets[i])return;ex.sets[i][k]=v;if(k==='kg'&&v!==''&&v!=null){for(let j=i+1;j<ex.sets.length;j++){if(ex.sets[j].kg===''||ex.sets[j].kg==null){ex.sets[j].kg=v;const el=document.querySelector('input[onchange*="draftSet(\''+exid+'\','+j+',\'kg\'"]');if(el)el.value=v}}}save()}
function addDraftSet(exid){if(!S.draft)return;const ex=S.draft.exercises.find(x=>x.id===exid);if(!ex)return;const prev=ex.sets[ex.sets.length-1]||{};ex.sets.push({kg:prev.kg||'',reps:prev.reps||'10',rir:prev.rir||''});save();render()}
function removeDraftSet(exid,i){const ex=S.draft&&S.draft.exercises.find(x=>x.id===exid);if(!ex)return;if(ex.sets.length===1){ex.sets[0]={kg:'',reps:'10',rir:''}}else ex.sets.splice(i,1);save();render()}
function removeDraftExercise(exid){if(!S.draft)return;S.draft.exercises=S.draft.exercises.filter(x=>x.id!==exid);save();render()}
function finishWorkout(){const d=S.draft;if(!d||!d.exercises.length)return alert('Ajoute au moins un exercice avant de terminer.');const rows=[];for(const ex of d.exercises){for(let i=0;i<ex.sets.length;i++){const z=ex.sets[i],kg=n(z.kg),reps=n(z.reps),rir=n(z.rir);if(!ok(kg)||kg<0||!Number.isInteger(reps)||reps<1)return alert('Complète le poids et les répétitions de chaque série, ou supprime les séries inutilisées.');rows.push({id:uid(),d:d.d,ex:ex.name,kg,reps,sets:1,rir:ok(rir)?rir:null,rest:null})}}const started=Date.parse(d.startedAt||''),durationSeconds=Number.isFinite(started)?Math.max(0,Math.round((Date.now()-started)/1000)):null;const session={id:d.id,d:d.d,type:d.type,startedAt:d.startedAt||null,endedAt:new Date().toISOString(),durationSeconds,volume:rows.reduce((sum,x)=>sum+x.kg*x.reps,0),exercises:d.exercises.map(x=>({name:x.name,group:x.group,sets:x.sets.map(z=>({kg:n(z.kg),reps:n(z.reps),rir:ok(n(z.rir))?n(z.rir):null}))}))};S.sets.push(...rows);S.sessions.push(session);S.lastSessionId=session.id;S.draft=null;day=session.d;save();render();toast('Séance enregistrée')}
function sessionMetrics(x){const sets=(x.exercises||[]).flatMap(e=>e.sets||[]);return{exercises:(x.exercises||[]).length,sets:sets.length,volume:sets.reduce((sum,z)=>sum+(ok(Number(z.kg))?Number(z.kg):0)*(ok(Number(z.reps))?Number(z.reps):0),0),duration:ok(x.durationSeconds)?Math.round(x.durationSeconds/60):null}}
function sessionSummaryHTML(){const x=(S.sessions||[]).find(s=>s.id===S.lastSessionId);if(!x)return '';const m=sessionMetrics(x),duration=m.duration===null?'Non renseignée':(m.duration<60?m.duration+' min':Math.floor(m.duration/60)+' h '+String(m.duration%60).padStart(2,'0')+' min');return '<section class="card workout-summary"><div class="hero-kicker">SÉANCE TERMINÉE</div><div class="split"><h2>Bilan de ta séance</h2><span class="tag good">Enregistrée</span></div><p class="mu">'+esc(x.type)+' · '+fd(x.d)+'</p><div class="g3"><div class="metric"><div class="mu">Exercices</div><div class="big">'+m.exercises+'</div></div><div class="metric"><div class="mu">Séries</div><div class="big">'+m.sets+'</div></div><div class="metric"><div class="mu">Durée</div><div class="big">'+duration+'</div></div></div><div class="metric" style="margin-top:10px"><div class="mu">Volume total (charge × répétitions)</div><div class="big">'+r(m.volume,0)+' kg</div></div><h3>Exercices réalisés</h3>'+x.exercises.map(e=>'<div class="li"><span><b>'+esc(e.name)+'</b><br><span class="mu">'+(e.sets||[]).length+' séries · '+(e.sets||[]).map(z=>r(Number(z.kg),1)+' kg × '+r(Number(z.reps))).join(' · ')+'</span></span></div>').join('')+'<button type="button" class="p secondary" onclick="S.lastSessionId=null;save();render()">Masquer le bilan</button></section>'}
function workoutHistory(){const a=[...(S.sessions||[])].sort((x,y)=>y.d.localeCompare(x.d));return a.slice(0,3).map(x=>'<div class="workout-history-row"><div><b>'+esc(x.type)+'</b><small>'+fd(x.d)+' · '+x.exercises.length+(x.exercises.length>1?' exercices · ':' exercice · ')+x.exercises.reduce((n,e)=>n+e.sets.length,0)+' séries</small><small>'+x.exercises.map(e=>esc(e.name)).join(' · ')+'</small></div><span class="tag">Terminée</span></div>').join('')||'<div class="mutedbox">Tes séances terminées apparaîtront ici.</div>'}
function vSession(){const d=S.draft;
if(!d){const summary=sessionSummaryHTML();const types=WORKOUT_TYPES.filter(x=>x[0]!=='LIBRE').map(([key,label,sub,ico])=>'<button type="button" class="workout-type-card" onclick="startWorkout(\''+key+'\')"><span class="workout-type-icon">'+ico+'</span><b>'+label+'</b><small>'+sub+'</small></button>').join('');return summary+'<section class="workout-hero"><div class="hero-kicker">TON CARNET · MUSCULATION</div><h2>On s’entraîne ?</h2><p>Choisis ton type de séance. Tu ajouteras ensuite les machines et tes séries.</p></section><section class="card"><div class="split"><h2>Choisir une séance</h2><span class="tag">6 formats</span></div><div class="workout-type-grid">'+types+'</div><button type="button" class="workout-free-link" onclick="startWorkout(\'LIBRE\')">＋ Créer une séance libre</button><label class="workout-date">Date<input type="date" value="'+day+'" onchange="day=this.value||day;render()"></label></section><section class="card workout-history"><div class="split"><h2>Historique récent</h2><span class="tag">'+(S.sessions||[]).length+' séance(s)</span></div>'+workoutHistory()+'</section>'}
const count=d.exercises.reduce((n,x)=>n+x.sets.length,0),done=d.exercises.filter(x=>x.sets.every(z=>ok(n(z.kg))&&ok(n(z.reps)))).length;
const cards=d.exercises.map(ex=>'<article class="workout-ex-card"><div class="workout-ex-head"><div><span class="tag">'+esc(ex.group||'Musculation')+'</span><h3>'+esc(ex.name)+'</h3></div><button type="button" class="x" onclick="removeDraftExercise(\''+ex.id+'\')" aria-label="Supprimer '+esc(ex.name)+'">×</button></div><div class="workout-set-head"><span>SÉRIE</span><span>POIDS (KG)</span><span>RÉPÉTITIONS</span><span></span></div>'+ex.sets.map((z,i)=>'<div class="workout-set-row"><b>'+(i+1)+'</b><label class="workout-set-field"><span>Poids · kg</span><input aria-label="Poids série '+(i+1)+' en kilogrammes" type="number" min="0" step="0.5" placeholder="Ex. 20" value="'+esc(z.kg)+'" onchange="draftSet(\''+ex.id+'\','+i+',\'kg\',this.value)"></label><label class="workout-set-field"><span>Répétitions</span><input aria-label="Répétitions série '+(i+1)+'" type="number" min="1" step="1" placeholder="Ex. 10" value="'+esc(z.reps)+'" onchange="draftSet(\''+ex.id+'\','+i+',\'reps\',this.value)"></label><button type="button" class="x" onclick="removeDraftSet(\''+ex.id+'\','+i+')" aria-label="Supprimer série '+(i+1)+'">−</button></div>').join('')+'<details class="workout-rir"><summary>Option avancée : effort (RIR)</summary><p>Combien de répétitions tu aurais encore pu faire à la fin de la série ?</p>'+ex.sets.map((z,i)=>'<label><span>Série '+(i+1)+'</span><input aria-label="RIR série '+(i+1)+'" type="number" min="0" max="10" placeholder="Non renseigné" value="'+esc(z.rir)+'" onchange="draftSet(\''+ex.id+'\','+i+',\'rir\',this.value)"></label>').join('')+'</details><p class="workout-set-hint">Astuce : le poids saisi préremplit les séries suivantes si elles sont vides. Tu peux toujours les modifier.</p><button type="button" class="workout-add-set" onclick="addDraftSet(\''+ex.id+'\')">＋ Ajouter une série</button></article>').join('');
const groups=['Tous',...Object.keys(LIBS)];
return '<section class="workout-active-head"><div><div class="hero-kicker">'+esc(d.type)+' · EN COURS</div><h2>Ta séance</h2><p class="mu">Renseigne tes séries au fur et à mesure. Tu peux ajouter d’autres exercices adaptés à cette séance.</p></div><button type="button" class="p sm secondary" onclick="cancelWorkout()">Annuler</button></section><section class="card workout-date-card"><label>Date<input type="date" value="'+d.d+'" onchange="S.draft.d=this.value;day=this.value;save()"></label><div class="workout-progress"><div class="split"><span>'+d.exercises.length+(d.exercises.length>1?' exercices · ':' exercice · ')+count+' séries</span><b>'+done+' / '+d.exercises.length+' prêts</b></div><div class="bar"><i style="width:'+(d.exercises.length?done/d.exercises.length*100:0)+'%"></i></div></div><div class="actions" style="margin-top:10px"><span class="mu">Chrono de repos :</span>'+[60,90,120,180].map(z=>'<button type="button" class="p sm secondary" onclick="startRest('+z+')">'+Math.floor(z/60)+':'+String(z%60).padStart(2,'0')+'</button>').join('')+'</div></section>'+(cards||'<div class="mutedbox workout-empty">Ta séance est vide pour le moment. Ajoute ta première machine ci-dessous.</div>')+'<details class="card workout-picker" '+(d.exercises.length?'':'open')+'><summary><span><b>＋ Ajouter un exercice</b><small>'+workoutLibraryCount()+' exercices adaptés à '+esc(d.type==='FULL BODY'?'Full Body':d.type)+'</small></span><span class="workout-picker-chevron">⌄</span></summary><div class="workout-picker-inner"><input type="search" value="'+esc(workoutSearch)+'" oninput="workoutSearchInput(this.value)" placeholder="Rechercher un exercice…"><div class="workout-filter-row"><label class="workout-filter-select">Matériel<select onchange="workoutEquipFilter(this.value)">'+[['Tous','Tous les matériels'],['M','Machines'],['H','Haltères'],['B','Barres'],['C','Poids du corps'],['P','Poulies']].map(([v,l])=>'<option value="'+v+'"'+(workoutEquip===v?' selected':'')+'>'+l+'</option>').join('')+'</select></label><label class="workout-filter-select">Muscle<select onchange="workoutFilter(this.value)">'+['Tous',...workoutAllowedGroups()].filter((g,i,a)=>a.indexOf(g)===i).map(g=>'<option value="'+esc(g)+'"'+(workoutGroup===g?' selected':'')+'>'+esc(g)+'</option>').join('')+'</select></label></div><p class="workout-result-count"><b id="workout-result-count">'+workoutLibraryCount()+'</b> exercices disponibles pour cette séance</p><div id="workout-machine-list" class="workout-machine-list">'+workoutLibraryHTML()+'</div></div></details><section class="card workout-finish"><div class="split"><div><h2>Fin de séance</h2><p class="mu">'+d.exercises.length+(d.exercises.length>1?' exercices · ':' exercice · ')+count+' séries renseignées</p></div><span class="tag">'+done+'/'+d.exercises.length+' prêts</span></div><button class="p" style="width:100%" onclick="finishWorkout()" '+(!d.exercises.length?'disabled':'')+'>Terminer et enregistrer</button><p class="mu">Vérifie que chaque série contient un poids et un nombre de répétitions.</p></section>'}
function vForce(){return vSession()+'<details class="ux-fold" data-ux-key="force-muscles"><summary>Récupération musculaire <span class="ux-fold-note">Body Tracker</span></summary><div class="ux-fold-inner">'+bodyTracker()+'</div></details><details class="ux-fold" data-ux-key="force-week"><summary>Programme hebdomadaire <span class="ux-fold-note">Répartition et planification</span></summary><div class="ux-fold-inner">'+vWeek()+'</div></details><details class="ux-fold" data-ux-key="force-old"><summary>Carnet, bibliothèque et outils <span class="ux-fold-note">Historique détaillé et progression</span></summary><div class="ux-fold-inner">'+vForceLegacy()+'</div></details>'}

let selectedExercise='';
function vPro(){const o=(a,cur)=>a.map(([v,l])=>`<option value="${v}"${String(v)===String(cur)?' selected':''}>${l}</option>`).join('');const t=targets(),ad=adaptiveAdvice();return `<div class="card"><h2>Profil et objectifs</h2><form onsubmit="savePro(event)"><div class="row"><label>Taille (cm)<input name="h" type="number" min="1" step="0.1" value="${pv('h')}" required></label><label>Âge<input name="age" type="number" min="1" max="120" value="${pv('age')}" required></label><label>Sexe utilisé pour l'estimation<select name="sex">${o([['M','Homme'],['F','Femme']],S.p.sex)}</select></label></div><div class="row" style="margin-top:8px"><label>Activité hors sport<select name="act">${o([[1.2,'Sédentaire'],[1.375,'Légère'],[1.55,'Active'],[1.725,'Très active']],S.p.act)}</select></label><label>Poids cible (kg)<input name="gw" type="number" min="1" step="0.1" value="${pv('gw')}"></label><label>Protéines (g/kg)<input name="pk" type="number" min="0.5" max="3" step="0.1" value="${S.p.pk}"></label><label>Sport ajouté au budget (%)<input name="eb" type="number" min="0" max="100" step="10" value="${S.p.eb}"></label><label>Séances par semaine (objectif)<input name="wg" type="number" min="1" max="7" value="${S.p.wg||4}"></label><label>Surplus / déficit (kcal)<input name="goal" type="number" step="50" value="${S.p.goal}" placeholder="-300 ou +200"></label></div><button class="p">Enregistrer le profil</button></form>${t?`<div class="g3" style="margin-top:16px"><div><div class="mu">Métabolisme de base estimé</div><b>${r(t.bmr)} kcal</b></div><div><div class="mu">Maintien estimé</div><b>${r(t.base)} kcal</b></div><div><div class="mu">Cible configurée</div><b>${r(t.target)} kcal</b></div></div>`:''}<p class="mu">Estimations à partir de Mifflin–St Jeor et d'un facteur d'activité. Ce ne sont pas des mesures directes de ton métabolisme.</p></div><div class="card"><h2>Ajustement indicatif des calories</h2><p>${esc(ad.message)}</p>${ad.trend?`<p class="mu">Tendance estimée : <b>${esc(ad.trend)}</b> · objectif : ${ad.goalType==='perte'?'perte de poids':ad.goalType==='prise'?'prise de poids':'stabilité'}.</p>`:''}<p class="mu">Cette suggestion est volontairement limitée à 100 kcal/j et n’est jamais appliquée automatiquement. Elle dépend de pesées régulières et de repas enregistrés de façon assez complète ; eau, sel, digestion et entraînement peuvent brouiller la tendance.</p>${ad.delta?`<button class="p secondary" onclick="applyAdaptive(${ad.delta})">Appliquer ${ad.delta>0?'+':''}${ad.delta} kcal/j à ma cible</button>`:''}</div><div class="card"><h2>Sauvegardes et données</h2><p class="mu">La sauvegarde simple contient les données de suivi. La sauvegarde complète inclut aussi les photos : le fichier peut être volumineux, conserve-le en lieu sûr et évite de le partager.</p><div class="row"><button class="p" onclick="exp()">Exporter données (JSON)</button><button class="p secondary" onclick="csvOut()">Exporter en CSV (Excel)</button><button class="p" onclick="expFull()">Sauvegarde complète + photos</button><label class="p secondary">Importer données<input type="file" accept=".json,application/json" hidden onchange="imp(this)"></label><label class="p secondary">Restaurer sauvegarde complète<input type="file" accept=".json,application/json" hidden onchange="impFull(this)"></label><button class="p orange" onclick="reset()">Tout effacer</button></div>${bk()}</div><div class="card"><h2>Vie privée</h2><p class="mu">Les photos et données restent dans ce navigateur sauf si tu les exportes ou utilises volontairement une fonction en ligne. La recherche Open Food Facts nécessite une connexion et transmet la requête au service.</p></div>`}
function vRecettes(){
const list=S.recipes.map((r,i)=>{
const portions=Math.max(1,r.portions||1);
return '<article class="recipe-card"><div class="recipe-card-top"><div><div class="hero-kicker">RECETTE MAISON</div><h3>'+esc(r.name)+'</h3><p class="mu">'+r.ingredients.length+' ingrédient(s) · '+portions+' portion(s)</p></div><button class="x" onclick="delRecipe('+i+')" aria-label="Supprimer">×</button></div><div class="recipe-nutrition"><div><b>'+Math.round((r.kcal||0)/portions)+'</b><small>kcal / portion</small></div><div><b>'+Math.round((r.p||0)/portions)+' g</b><small>protéines</small></div><div><b>'+Math.round((r.c||0)/portions)+' g</b><small>glucides</small></div><div><b>'+Math.round((r.f||0)/portions)+' g</b><small>lipides</small></div></div><div class="recipe-add-row"><label>Portions<input id="rp'+i+'" type="number" min="0.25" step="0.25" value="1" aria-label="Nombre de portions"></label><label>Repas<select id="rs'+i+'" aria-label="Moment du repas">'+SLOTS.map(z=>'<option>'+z+'</option>').join('')+'</select></label><button class="p" onclick="addRecipeMeal('+i+')">Ajouter au journal</button></div></article>';
}).join('');
return '<section class="hero"><div><div class="hero-kicker">NUTRITION · RECETTES</div><div class="hero-title">Tes plats, sans prise de tête.</div><div class="hero-sub">Enregistre tes recettes une fois, puis ajoute une portion à ton journal en un geste.</div></div></section><div class="recipe-layout"><section class="card"><div class="split"><h2>Créer une recette</h2><span class="tag">Étape 1/2</span></div><form onsubmit="addRecipe(event)" id="recipeForm"><label>Nom du plat<input name="name" required maxlength="70" placeholder="Ex. pâtes au poulet"></label><label>Nombre de portions obtenues<input name="portions" type="number" min="1" step="1" value="2" required></label><label>Ingrédients <span class="mu">— un par ligne</span><textarea name="ingredients" rows="5" placeholder="Riz cuit ; 250&#10;Poulet cuit (blanc) ; 200" required></textarea></label><details class="recipe-help"><summary>Comment renseigner les ingrédients ?</summary><div class="ux-fold-inner"><p class="mu">Utilise le nom exact de l’aliment dans ta base, puis un point-virgule et le poids en grammes.</p><p><code>Riz cuit ; 250</code><br><code>Poulet cuit (blanc) ; 200</code></p><p class="mu">Les macros sont calculées à partir des valeurs de ta base alimentaire.</p></div></details><button class="p block" type="submit">Enregistrer ma recette</button></form></section><section class="card"><div class="split"><h2>Mes recettes</h2><span class="tag">'+S.recipes.length+' enregistrée(s)</span></div><label>Rechercher un plat<input type="search" id="recipeSearch" placeholder="Ex. poulet, riz, pâtes…" oninput="filterRecipes(this.value)"></label><div id="recipeList" class="recipe-list">'+(list||'<div class="recipe-empty"><b>Ta première recette t’attend</b><p class="mu">Crée un plat puis ajoute-le à ton journal sans ressaisir les ingrédients.</p></div>')+'</div><p id="recipeNoResults" class="mu" hidden>Aucune recette ne correspond à cette recherche.</p></section></div>';
}
function filterRecipes(q){const query=String(q||'').trim().toLowerCase();let count=0;document.querySelectorAll('#recipeList .recipe-card').forEach(el=>{const show=el.textContent.toLowerCase().includes(query);el.hidden=!show;if(show)count++});const empty=document.getElementById('recipeNoResults');if(empty)empty.hidden=count>0}

function addRecipe(e){e.preventDefault();const f=e.target,name=f.name.value.trim(),portions=Math.max(1,Math.floor(n(f.portions.value))),lines=f.ingredients.value.split('\n').map(x=>x.trim()).filter(Boolean),ingredients=[];for(const line of lines){const parts=line.split(';'),nm=(parts[0]||'').trim(),g=n(parts[1]),food=findFood(nm);if(!food||!ok(g)||g<=0)return alert(`Ingrédient invalide ou introuvable : ${nm}. Utilise le nom exact de la base et « nom ; grammes ».`);ingredients.push({name:food[0],g,k:food[1]*g/100,p:food[2]*g/100,c:food[3]*g/100,f:food[4]*g/100})}if(!ingredients.length)return alert('Ajoute au moins un ingrédient.');S.recipes.push({id:uid(),name,portions,ingredients,kcal:sum(ingredients,'k'),p:sum(ingredients,'p'),c:sum(ingredients,'c'),f:sum(ingredients,'f')});save();render()}
function addRecipeMeal(i){const x=S.recipes[i];if(!x)return;const q=n($('#rp'+i).value),slot=$('#rs'+i).value||'Déjeuner',p=ok(q)&&q>0?q:1,k=p/x.portions;S.meals.push({id:uid(),d:day,slot,name:`${x.name} (${String(p).replace('.',',')} portion${p>1?'s':''})`,g:null,k:x.kcal*k,p:x.p*k,c:x.c*k,f:x.f*k,source:'recette'});save();tab='jour';render()}
function delRecipe(i){if(!confirm('Supprimer cette recette ?'))return;S.recipes.splice(i,1);save();render()}
const OFFC={};
async function offGet(url,ms=9000){const c=new AbortController(),t=setTimeout(()=>c.abort(),ms);try{const res=await fetch(url,{signal:c.signal,headers:{Accept:'application/json'}});if(!res.ok){const e=Error('http');e.status=res.status;throw e}return await res.json()}finally{clearTimeout(t)}}
const offMap=p=>{const m=p.nutriments||{},g=k=>{const v=parseFloat(m[k]);return Number.isFinite(v)?v:null},kj=g('energy_100g'),kc=g('energy-kcal_100g')??(kj!==null?kj/4.184:null),nm=p.product_name||p.product_name_fr||'',br=Array.isArray(p.brands)?p.brands[0]:String(p.brands||'').split(',')[0];return{name:[nm,br].filter(Boolean).join(' - '),f:[0,kc,g('proteins_100g'),g('carbohydrates_100g'),g('fat_100g')]}};
const offOk=a=>(a||[]).map(offMap).filter(x=>x.name&&ok(x.f[1]));
function offShow(a){OFF=a;$('#off').innerHTML=a.length?a.map((x,i)=>`<div class="li"><span>${esc(x.name)}<br><span class="mu">${r(x.f[1])} kcal · P ${r(x.f[2]||0,1)} · G ${r(x.f[3]||0,1)} · L ${r(x.f[4]||0,1)} / 100 g</span></span><button class="p sm" onclick="useOff(${i})">Enregistrer l'aliment</button></div>`).join(''):'<p class="mu">Aucun résultat avec des valeurs énergétiques. Essaie un autre mot, ou saisis les valeurs à la main.</p>'}
async function offSearch(e){e.preventDefault();const q=e.target.q.value.trim(),el=$('#off'),bar=/^\d{8,14}$/.test(q);if(!q)return;if(!bar&&q.length<3){el.innerHTML='<p class="mu">Tape au moins 3 caractères.</p>';return}
 if(OFFC[q]){offShow(OFFC[q]);return}
 el.innerHTML='<p class="mu">Recherche en cours…</p>';const F='code,product_name,brands,nutriments';let L=null,err=null;
 const tries=bar?[()=>offGet(`https://world.openfoodfacts.org/api/v2/product/${encodeURIComponent(q)}.json?fields=${F}`).then(j=>offOk(j.product?[j.product]:[]))]:[
  ()=>offGet(`https://search.openfoodfacts.org/search?q=${encodeURIComponent(q)}&langs=fr,en&page_size=12&fields=${F}`).then(j=>offOk(j.hits)),
  ()=>offGet(`https://world.openfoodfacts.org/cgi/search.pl?search_terms=${encodeURIComponent(q)}&search_simple=1&action=process&json=1&page_size=12&fields=${F}`).then(j=>offOk(j.products))];
 for(const t of tries){try{L=await t();if(L.length)break}catch(x){err=x}}
 if(L===null){const st=err&&err.status;el.innerHTML=`<p class="mu">Open Food Facts ne répond pas${st?` (erreur ${st})`:err&&err.name==='AbortError'?' (délai dépassé)':''}. ${st===503||st===429?'Le service est saturé ou limite les requêtes (environ 10 recherches par minute) : réessaie dans une minute.':'Vérifie ta connexion et réessaie dans un instant, ou saisis les valeurs à la main.'}</p>`;return}
 if(L.length)OFFC[q]=L;offShow(L)}
function useOff(i){const x=OFF[i];if(!x)return;const nm=x.name.slice(0,100);S.foods.unshift([nm,x.f[1],x.f[2]||0,x.f[3]||0,x.f[4]||0]);save();tab='jour';render();const f=$('[name=food]');if(f){f.value=nm;const g=$('[name=g]');if(g)g.focus()}}
function idb(){if(DB)return DB;DB=new Promise((resolve,reject)=>{if(!('indexedDB'in window)){reject(Error('IndexedDB indisponible'));return}const q=indexedDB.open(PHOTO_DB,1);q.onupgradeneeded=()=>{if(!q.result.objectStoreNames.contains('p'))q.result.createObjectStore('p',{keyPath:'id',autoIncrement:true});};q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)});return DB}
