function vPlus(){const I=[['cardio','Cardio','Marche, vélo et endurance'],['cal','Calendrier','Retrouver tes journées'],['pro','Profil et sauvegardes','Objectifs et gestion des données']];return `<div class="card"><div class="hero-kicker">OUTILS COMPLÉMENTAIRES</div><h2>Plus</h2><p class="mu">Les outils que tu utilises moins souvent sont regroupés ici.</p>${I.map(([k,l,d])=>`<button class="li" style="width:100%;background:none;border:0;border-top:1px solid #ffffff10;color:var(--ink);text-align:left;font:inherit;cursor:pointer" onclick="tab='${k}';render()"><span><b>${l}</b><br><span class="mu">${d}</span></span><span class="mu">›</span></button>`).join('')}</div>`}
const BT=[['jour','Accueil','<path d="M3 11l9-8 9 8v10h-6v-6H9v6H3z"/>'],['force','Musculation','<path d="M6 7v10M18 7v10M3 10v4M21 10v4M6 12h12"/>'],['progression','Progression','<path d="M3 17l6-6 4 4 8-8"/><path d="M15 7h6v6"/>'],['plus','Plus','<circle cx="5" cy="12" r="1.3"/><circle cx="12" cy="12" r="1.3"/><circle cx="19" cy="12" r="1.3"/>']];
const bnav=()=>`<nav class="bnav" aria-label="Navigation principale">${BT.map(([k,l,ic])=>{const aliases=k==='progression'?['mes','evo','ph']:k==='plus'?['recettes','cal','pro','cardio']:[];const on=k===tab||aliases.includes(tab);return `<button class="${on?'on':''}"${on?' aria-current="page"':''} onclick="tab='${k}';render()"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ic}</svg>${l}</button>`}).join('')}</nav>`;
document.addEventListener('focusin',e=>{if(e.target&&e.target.type==='number'){try{e.target.select()}catch(x){}}});
