const TPL={Push:['Développé couché','Développé incliné haltères','Développé militaire','Élévations latérales','Extension poulie haute','Dips triceps'],Pull:['Tractions','Rowing barre','Tirage vertical','Face pull','Curl barre EZ','Curl marteau'],Legs:['Squat','Presse à cuisses','Soulevé de terre roumain','Leg curl allongé','Leg extension','Mollets debout'],Upper:['Développé couché','Rowing barre','Développé militaire','Tirage vertical','Curl haltères','Extension corde'],Lower:['Squat','Soulevé de terre roumain','Fentes marchées','Leg curl assis','Hip thrust','Mollets assis'],'Full body A':['Squat','Développé couché','Rowing barre','Développé militaire','Crunch poulie'],'Full body B':['Soulevé de terre','Développé incliné haltères','Tractions','Fentes','Planche'],'Bras & épaules':['Développé haltères assis','Élévations latérales','Oiseau haltères','Curl pupitre','Barre au front','Curl marteau'],Abdos:['Relevé de jambes','Crunch poulie','Roue abdominale','Planche','Russian twist'],'Débutant A':['Chest press machine','Tirage vertical','Presse à cuisses','Rowing assis machine','Élévations latérales machine','Curl biceps machine','Crunch machine'],'Débutant B':['Développé incliné machine','High row machine','Leg curl assis','Développé épaules machine','Oiseau machine','Extension triceps machine','Mollets assis']};
let tplSel='',guideEdit=false;
function guideSug(ex){const t=daySets().filter(x=>x.ex===ex).pop();if(t)return{kg:t.kg,reps:t.reps,txt:`Dernière série : ${r(t.reps)} × ${r(t.kg,1)} kg`};const L=S.sets.filter(x=>x.ex===ex&&x.d<day).sort((a,b)=>b.d.localeCompare(a.d));if(!L.length)return{kg:'',reps:8,txt:'Première fois : choisis une charge confortable.'};const b=L.filter(x=>x.d===L[0].d).reduce((m,x)=>e1(x)>e1(m)?x:m),up=b.reps>=10;return{kg:up?b.kg+2.5:b.kg,reps:up?8:b.reps+1,txt:`Dernière séance : ${r(b.sets)} × ${r(b.reps)} à ${r(b.kg,1)} kg. Suggestion : ${up?r(b.kg+2.5,1)+' kg':'même charge, '+r(b.reps+1)+' reps'}.`}}
const tpls=()=>{const all={...TPL,...(S.tpl||{})};(S.tplHidden||[]).forEach(k=>delete all[k]);return all};
function tplCfg(ex){const c=S.tplCfg&&S.tplCfg[tplSel]&&S.tplCfg[tplSel][ex];return{sets:Math.max(1,Math.min(10,Math.round(n(c&&c.sets)||3))),reps:Math.max(1,Math.min(30,Math.round(n(c&&c.reps)||10)))}}
function tplEditToggle(){guideEdit=!guideEdit;render()}
function tplAddExercise(){const f=$('#guide-add-ex');const ex=f&&f.value;if(!ex||!tplSel)return;const T=tpls();if((T[tplSel]||[]).some(x=>fold(x)===fold(ex)))return toast('Cet exercice est déjà dans la séance');S.tpl=S.tpl||{};S.tpl[tplSel]=[...(T[tplSel]||[]),ex];S.tplHidden=(S.tplHidden||[]).filter(x=>x!==tplSel);save();render();toast('Exercice ajouté')}
function tplRemoveExercise(i){if(!tplSel)return;const T=tpls(),a=[...(T[tplSel]||[])];if(!a[i])return;if(!confirm('Retirer « '+a[i]+' » de cette séance ?'))return;a.splice(i,1);S.tpl=S.tpl||{};S.tpl[tplSel]=a;save();render()}
function tplMoveExercise(i,d){const T=tpls(),a=[...(T[tplSel]||[])],j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];S.tpl=S.tpl||{};S.tpl[tplSel]=a;save();render()}
function tplSetTarget(ex,k,v){S.tplCfg=S.tplCfg||{};S.tplCfg[tplSel]=S.tplCfg[tplSel]||{};S.tplCfg[tplSel][ex]=S.tplCfg[tplSel][ex]||{};S.tplCfg[tplSel][ex][k]=Math.max(1,Math.min(k==='sets'?10:30,Math.round(n(v)||1)));save()}
function tplRename(){if(!tplSel)return;const nm=(prompt('Nouveau nom de la séance :',tplSel)||'').trim().slice(0,30);if(!nm||nm===tplSel)return;if(tpls()[nm])return alert('Une séance porte déjà ce nom.');const old=tplSel;S.tpl=S.tpl||{};S.tpl[nm]=[...(tpls()[old]||[])];if(TPL[old]||Object.prototype.hasOwnProperty.call(S.tpl,old))S.tplHidden=[...new Set([...(S.tplHidden||[]),old])];if(S.tpl[old]&&old!==nm)delete S.tpl[old];if(S.tplCfg&&S.tplCfg[old]){S.tplCfg[nm]=S.tplCfg[old];delete S.tplCfg[old]}tplSel=nm;save();render();toast('Séance renommée')}
