Object.entries(EXTRA_EXERCISES).forEach(([g,names])=>names.forEach(nm=>{const code=EXTRA_EQUIPMENT[nm]||'C';if(!LIBS[g].split(',').some(x=>fold(x.split('|')[0])===fold(nm)))LIBS[g]+=','+nm+'|'+code}));
const MACHINE_LIBRARY={
 Pectoraux:['Chest press','Chest press convergente','Développé incliné machine','Développé décliné machine','Pec deck / Butterfly','Écarté pectoraux machine'],
 Dos:['Rowing assis machine','Rowing convergent','High row machine','Tirage vertical machine','Pullover machine','Machine lombaires'],
 Épaules:['Développé épaules machine','Élévations latérales machine','Oiseau machine / Reverse pec deck','Shrug machine'],
 Biceps:['Curl biceps machine','Curl pupitre machine'],
 Triceps:['Extension triceps machine','Dips assistés machine'],
 Quadriceps:['Presse à cuisses','Presse horizontale','Hack squat','Pendulum squat','Leg extension'],
 Ischios:['Leg curl assis','Leg curl allongé','Leg curl debout'],
 Fessiers:['Hip thrust machine','Glute drive machine','Abducteurs machine','Adducteurs machine','Kickback machine'],
 Mollets:['Mollets assis machine','Mollets debout machine','Mollets à la presse'],
 Abdos:['Crunch machine','Rotation du buste machine']
};
Object.entries(MACHINE_LIBRARY).forEach(([g,names])=>names.forEach(nm=>{if(!LIBS[g])LIBS[g]='';const exists=LIBS[g].split(',').some(x=>fold(x.split('|')[0])===fold(nm));if(!exists)LIBS[g]+=(LIBS[g]?',':'')+nm+'|M'}));

const EQ={B:'Barre',H:'Haltères',M:'Machine',P:'Poulie',C:'Poids du corps'};
const LIB=Object.entries(LIBS).flatMap(([g,s])=>s.split(',').map(x=>{const [nm,e]=x.split('|');return{n:nm,g,e}}));
EXS=LIB.map(x=>x.n);
const GRX=[[/leg extension|extension jambes|quadriceps|presse|squat|fente|jambe/,'Quadriceps'],[/curl|biceps/,'Biceps'],[/triceps|extension|dips/,'Triceps'],[/mollet/,'Mollets'],[/ischio|leg curl|souleve/,'Ischios'],[/fessier|hip|pont/,'Fessiers'],[/pec|couche|pompe|ecart|developpe|chest press/,'Pectoraux'],[/epaule|militaire|lateral|oiseau/,'Épaules'],[/tirage|row|tract|dos|pull|high row/,'Dos'],[/abdo|crunch|gainage|planche/,'Abdos']];
const grpOf=ex=>{const q=fold(ex);if(!q)return 'Autre';const a=LIB.find(x=>fold(x.n)===q)||LIB.find(x=>fold(x.n).includes(q)||q.includes(fold(x.n)));if(a)return a.g;const b=GRX.find(([re])=>re.test(q));return b?b[1]:'Autre'};
let libG='',libQ='';
const libFilter=()=>{const q=fold(libQ);return LIB.filter(x=>(!libG||x.g===libG)&&(!q||fold(x.n).includes(q)))};
const libList=L=>L.length?L.slice(0,40).map(x=>'<button type="button" class="li qsb" data-n="'+esc(x.n)+'" onclick="pickEx(this.dataset.n)"><span class="lib-eq-icon"><b>'+({'M':'▥','H':'⏣','B':'━','P':'↕','C':'●'}[x.e]||'•')+'</b><span>'+esc(x.n)+'<br><span class="mu">'+x.g+' · '+EQ[x.e]+'</span></span></span><span class="mu">+</span></button>').join(''):'<p class="mu">Aucun exercice trouvé.</p>';
function libRender(){const e=$('#libl');if(e)e.innerHTML=libList(libFilter())}
function pickEx(nm){const f=$('#setForm');if(!f)return;f.ex.value=nm;hintSet(f.ex);f.kg.focus();f.scrollIntoView({behavior:'smooth',block:'center'});toast(nm+' : prêt à saisir')}
function vLib(){return `<div class="card"><h2>Bibliothèque d'exercices</h2><div class="actions"><button class="p sm ${libG?'secondary':''}" onclick="libG='';render()">Tous</button>${Object.keys(LIBS).map(g=>`<button class="p sm ${libG===g?'':'secondary'}" data-g="${g}" onclick="libG=this.dataset.g;render()">${g}</button>`).join('')}</div><label style="margin-top:8px">Rechercher<input value="${esc(libQ)}" oninput="libQ=this.value;libRender()" placeholder="Ex. curl, squat, pec deck…"></label><div id="libl">${libList(libFilter())}</div><p class="mu">${LIB.length} exercices. Touche-en un pour le préparer dans le carnet.</p></div>`}
function vWeek(){const a=dstr(6),W=S.sets.filter(x=>x.d>=a&&x.d<=localDate()),by={};W.forEach(x=>{const g=grpOf(x.ex);by[g]=(by[g]||0)+x.sets});const days=new Set(W.map(x=>x.d)).size,wg=n(S.p.wg)||4,td=daySets(),prs=td.filter(x=>{const o=S.sets.filter(y=>y.ex===x.ex&&y.d<x.d);return o.length>0&&e1(x)>Math.max(...o.map(e1))}).length,hit=[...new Set(td.map(x=>grpOf(x.ex)))];
 const bars=Object.keys(LIBS).map(g=>{const c=by[g]||0;return `<div style="margin-top:8px"><div class="split mu"><span>${g}</span><span><b style="color:var(--ink)">${c}</b> séries</span></div><div class="bar" style="margin:4px 0 0"><i style="width:${Math.min(100,c/20*100)}%;background:${c>=10?'var(--m)':c>0?'var(--b)':'var(--line)'}"></i></div></div>`}).join('');
 return `<div class="card"><div class="split"><h2>Ta semaine</h2><span class="tag">${days} / ${wg} séances</span></div><div class="bar"><i style="width:${Math.min(100,days/wg*100)}%"></i></div>${td.length?`<p class="mu">Aujourd'hui : ${hit.join(', ')}${prs?` · ${prs} record${prs>1?'s':''}`:''}.</p>`:''}<details open><summary class="mu" style="cursor:pointer;padding:6px 0">Volume par muscle sur 7 jours (repère : 10 à 20 séries par muscle et par semaine)</summary>${bars}${by.Autre?`<p class="mu">Autres exercices : ${by.Autre} séries.</p>`:''}</details></div>`}
function toolWarm(x){const w=n(x),e=$('#tw'),ro=z=>Math.max(0,Math.round(z/2.5)*2.5);if(!e)return;if(!ok(w)||w<=0){e.textContent='Entre ta charge de travail pour obtenir les séries d\'échauffement.';return}e.innerHTML=[[.4,8],[.6,5],[.8,3],[.9,1]].map(([p,rp])=>`<div class="li"><span>${Math.round(p*100)} %</span><b>${r(ro(w*p),1)} kg × ${rp}</b></div>`).join('')+`<p class="mu">Puis tes séries de travail à ${r(w,1)} kg. Ajoute 1 série à vide ou à la barre × 10 si besoin.</p>`}
function toolPlates(){const t=n($('#pk1').value),bar=n($('#pk2').value),e=$('#tp');if(!e)return;if(!ok(t)||!ok(bar)||t<=bar){e.textContent='La charge visée doit dépasser le poids de la barre.';return}let side=(t-bar)/2;const out=[];[25,20,15,10,5,2.5,1.25].forEach(p=>{const c=Math.floor(side/p+1e-9);if(c){out.push(`${c} × ${String(p).replace('.',',')} kg`);side-=c*p}});e.innerHTML=`Par côté : <b style="color:var(--ink)">${out.join(' + ')||'aucun disque'}</b>${side>.01?`<br>Impossible à charger exactement : charge réelle ${r(t-side*2,2)} kg.`:''}`}
function tool1rm(ex){const e=$('#t1');if(!e)return;const L=S.sets.filter(x=>x.ex===ex);if(!L.length){e.textContent='';return}const b=Math.max(...L.map(e1));e.innerHTML=`<p class="mu">Meilleur 1RM estimé : ${r(b,1)} kg</p>`+[[95,2],[90,4],[85,6],[80,8],[75,10],[70,12],[60,15]].map(([p,rp])=>`<div class="li"><span>${p} % · environ ${rp} reps</span><b>${r(Math.round(b*p/100/2.5)*2.5,1)} kg</b></div>`).join('')}
function vTools(){const u=[...new Set(S.sets.map(x=>x.ex))];return `<div class="card"><h2>Outils de salle</h2><details><summary class="mu" style="cursor:pointer;padding:6px 0">Échauffement progressif</summary><label>Charge de travail (kg)<input type="number" min="1" step="0.5" oninput="toolWarm(this.value)"></label><div id="tw" class="mu" style="margin-top:8px"></div></details><details><summary class="mu" style="cursor:pointer;padding:6px 0">Calculateur de disques</summary><div class="row"><label>Charge visée (kg)<input id="pk1" type="number" min="1" step="0.5" oninput="toolPlates()"></label><label>Barre (kg)<input id="pk2" type="number" min="0" step="0.5" value="20" oninput="toolPlates()"></label></div><div id="tp" class="mu" style="margin-top:8px"></div></details><details><summary class="mu" style="cursor:pointer;padding:6px 0">Pourcentages de ton 1RM</summary><label>Exercice<select onchange="tool1rm(this.value)"><option value="">Choisir</option>${u.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select></label><div id="t1" class="mu" style="margin-top:8px"></div></details></div>`}
let tx0=0,ty0=0;document.addEventListener('touchstart',e=>{const t=e.changedTouches[0];tx0=t.clientX;ty0=t.clientY},{passive:true});
document.addEventListener('touchend',e=>{if(tab!=='jour'||(e.target.closest&&e.target.closest('input,select,textarea,svg,details,button')))return;const t=e.changedTouches[0],dx=t.clientX-tx0,dy=t.clientY-ty0;if(Math.abs(dx)>90&&Math.abs(dy)<45)shiftDay(dx<0?1:-1)},{passive:true});
const TABS=[['jour',"Accueil"],['force','Musculation'],['progression','Progression'],['plus','Plus']];
let uxOpenSections={};
function render(){document.querySelectorAll('main details[data-ux-key][open]').forEach(d=>uxOpenSections[d.dataset.uxKey]=true);const same=tab===lastTab,y=same?window.scrollY:0,snap=KEEP&&same?[...document.querySelectorAll('main [name]')].filter(e=>e.value&&e.form&&e.type!=='date').map(e=>[e.form.id||'',e.name,e.value]):[];KEEP=0;lastTab=tab;$('#app').innerHTML=`<header><h1>Suivi Forme <span class="tag">V16</span></h1><nav>${TABS.map(([k,l])=>`<button class="${k===tab||(k==='plus'&&['recettes','cal','pro','cardio'].includes(tab))?'on':''}" onclick="tab='${k}';render()">${l}</button>`).join('')}</nav></header><main>${({jour:vJour,mes:vMes,force:vForce,progression:vProgression,recettes:vRecettes,cardio:vCardio,evo:vEvo,cal:vCalendrier,ph:vPh,pro:vPro,plus:vPlus}[tab]||vJour)()}</main>${bnav()}${tab==='jour'?'<button class="fab" aria-label="Ajouter un aliment" onclick="fabGo()">+</button>':''}`;document.querySelectorAll('main details[data-ux-key]').forEach(d=>{if(uxOpenSections[d.dataset.uxKey])d.open=true});snap.forEach(([fi,nm,v])=>{const e=[...document.querySelectorAll('main [name="'+nm+'"]')].find(x=>x.form&&(x.form.id||'')===fi);if(e&&!e.value&&e.tagName!=='SELECT')e.value=v});window.scrollTo(0,y);if(QS&&$('#qsr'))qsDraw();if(tab==='ph'||(tab==='progression'&&progressView==='ph'))loadPhotos()}
try{if(navigator.storage&&navigator.storage.persist)navigator.storage.persist()}catch(e){}
try{if("serviceWorker"in navigator&&location.protocol.indexOf("http")===0)navigator.serviceWorker.register("sw.js")}catch(e){}
render();
